import { test, expect } from '@playwright/test';

test.describe('Search Filter - Exclude Term by Prefixing with "-"', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should exclude a term from search results by prefixing it with "-"', async ({ page }) => {
    // Setup: Fill in search input with a term
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('playwright');

    // Setup: Click the search button to trigger search
    const searchButton = page.getByRole('button', { name: 'Search' });
    await searchButton.click();

    // Verify search results are displayed
    const searchResults = page.getByRole('region', { name: 'Search Results' });
    await expect(searchResults).toBeVisible();

    // Verify initial results contain the term
    const resultItems = page.locator('[data-testid="search-result-item"]');
    await expect(resultItems).toHaveCount(3);

    // Verify the term 'playwright' is present in the results
    const playwrightResult = page.getByText('playwright');
    await expect(playwrightResult).toBeVisible();

    // Setup: Click the exclude button for the term
    const excludeButton = page.getByRole('button', { name: 'Exclude' });
    await excludeButton.click();

    // Verify the exclude button is disabled after click
    await expect(excludeButton).toBeDisabled();

    // Verify the term 'playwright' is no longer in the results
    await expect(playwrightResult).not.toBeVisible();

    // Verify the search results count is reduced
    await expect(resultItems).toHaveCount(2);

    // Verify the search input still has the term
    await expect(searchInput).toHaveValue('playwright');

    // Verify the exclude button is now available for other terms
    await expect(excludeButton).not.toBeDisabled();
  });

  test('should handle multiple excluded terms with "-" prefix', async ({ page }) => {
    // Setup: Fill in search input with multiple terms
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('playwright -test -script');

    // Setup: Click the search button to trigger search
    const searchButton = page.getByRole('button', { name: 'Search' });
    await searchButton.click();

    // Verify search results are displayed
    const searchResults = page.getByRole('region', { name: 'Search Results' });
    await expect(searchResults).toBeVisible();

    // Verify initial results contain all terms
    const resultItems = page.locator('[data-testid="search-result-item"]');
    await expect(resultItems).toHaveCount(5);

    // Verify each term is present in the results
    const playwrightResult = page.getByText('playwright');
    const testResult = page.getByText('test');
    const scriptResult = page.getByText('script');

    await expect(playwrightResult).toBeVisible();
    await expect(testResult).toBeVisible();
    await expect(scriptResult).toBeVisible();

    // Setup: Click the exclude button for 'test'
    const testExcludeButton = page.getByRole('button', { name: 'Exclude -test' });
    await testExcludeButton.click();

    // Verify the exclude button is disabled after click
    await expect(testExcludeButton).toBeDisabled();

    // Verify the term 'test' is no longer in the results
    await expect(testResult).not.toBeVisible();

    // Verify the search results count is reduced
    await expect(resultItems).toHaveCount(4);

    // Verify the search input still has the term
    await expect(searchInput).toHaveValue('playwright -test -script');

    // Verify the exclude button is now available for other terms
    await expect(testExcludeButton).not.toBeDisabled();
  });
});
